Section2DItemWrapper.Formula:
local gauge = _alignmentSnapshot.AlignmentGauge
local points = {getPoint3D(gauge / 2, 0), getPoint3D(gauge / 2 + 0.072, 0), getPoint3D(gauge / 2 + 0.111, -0.172), getPoint3D(gauge / 2 - 0.039, -0.172)}
return table.select(points, function(p) return RC_ApplyLiftAndRotate(this, _alignmentSnapshot.PointObjectDistanceAlong, p, _alignmentSnapshot.Cant) end)

local gauge = _alignmentSnapshot.AlignmentGauge
local points = {getPoint3D(-gauge / 2, 0), getPoint3D(-gauge / 2 - 0.072, 0), getPoint3D(-gauge / 2 - 0.111, -0.172), getPoint3D(-gauge / 2 + 0.039, -0.172)}
return table.select(points, function(p) return RC_ApplyLiftAndRotate(this, _alignmentSnapshot.PointObjectDistanceAlong, p, _alignmentSnapshot.Cant) end)
